dec=5; h=0.001*dec
def sim(p,d,Tm):
    Kpq,Kiq,Kqv,Kp,Tw,Kpv,Kpvs=p
    V=d['V'][::dec];th=d['th'][::dec];Vs=d['Vs'][::dec]
    V0=V[0];th0=th[0];P0=d['P'][0];Q0=d['Q'][0]
